import zipfile, re, sys
import xml.etree.ElementTree as ET

NS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
RNS = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}"

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group()
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx - 1

def row_of(ref):
    return int(re.search(r"\d+", ref).group()) - 1

def parse_shared_strings(data):
    root = ET.fromstring(data)
    out = []
    for si in root.findall(f"{NS}si"):
        out.append("".join(t.text or "" for t in si.iter(f"{NS}t")))
    return out

def parse_worksheet(data, shared):
    root = ET.fromstring(data)
    rows = {}
    for row in root.iter(f"{NS}row"):
        r = int(row.get("r")) - 1
        rows.setdefault(r, {})
        for c in row.findall(f"{NS}c"):
            ref = c.get("r")
            ci = col_to_idx(ref)
            t = c.get("t")
            v = c.find(f"{NS}v")
            is_el = c.find(f"{NS}is")
            if t == "inlineStr" and is_el is not None:
                val = "".join(x.text or "" for x in is_el.iter(f"{NS}t"))
            elif v is None:
                val = None
            elif t == "s":
                val = shared[int(v.text)]
            elif t == "b":
                val = v.text == "1"
            elif t == "str":
                val = v.text
            elif t == "e":
                val = "#" + (v.text or "")
            else:
                val = v.text
            rows[r][ci] = val
    return rows

def to_number(val):
    if val is None or isinstance(val, bool):
        return None
    if isinstance(val, (int, float)):
        return float(val)
    s = str(val).strip()
    if s == "":
        return None
    try:
        return float(s)
    except ValueError:
        return None

def col_letter(i):
    s = ""
    i += 1
    while i:
        i, rem = divmod(i - 1, 26)
        s = chr(65 + rem) + s
    return s

path = sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx"
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {rel.get("Id"): rel.get("Target") for rel in rels.findall(f"{RNS}Relationship")}
    sheets = []
    for sh in wb.iter(f"{NS}sheet"):
        target = rel_map[sh.get(f"{RNS}id")]
        if not target.startswith("xl/"):
            target = "xl/" + target
        sheets.append((sh.get("name"), target))
    shared = parse_shared_strings(z.read("xl/sharedStrings.xml")) if "xl/sharedStrings.xml" in names else []

    grand_total = 0.0
    for sname, target in sheets:
        rows = parse_worksheet(z.read(target), shared)
        print(f"===== Sheet: {sname} =====")
        if not rows:
            print("(empty)")
            continue
        max_r = max(rows) + 1
        max_c = max(max(cols) for cols in rows.values()) + 1
        header = "    " + "".join(f"{col_letter(c):>12}" for c in range(max_c))
        print(header)
        sheet_total = 0.0
        col_sums = [0.0] * max_c
        for r in range(max_r):
            cells = rows.get(r, {})
            line = f"{r+1:>3} "
            for c in range(max_c):
                val = cells.get(c)
                n = to_number(val)
                if n is not None:
                    sheet_total += n
                    col_sums[c] += n
                    line += f"{n:>12.2f}"
                else:
                    line += f"{str(val if val is not None else ''):>12}"
            print(line)
        print(f"Sheet numeric total: {sheet_total}")
        for c in range(max_c):
            print(f"  Column {col_letter(c)} sum: {col_sums[c]:.2f}")
        grand_total += sheet_total
        print()

    print(f"GRAND TOTAL (all numeric cells, all sheets): {grand_total:.2f}")

